  const runBlockUid = await createBlock(branchBlockUid, label);

  const items: Item[] = [];
  for (const upload of uploads) {
    const bytes = Uint8Array.from(atob(upload.base64), (c) => c.charCodeAt(0));
    const file = new File([bytes], upload.name, { type: "image/png" });
    const ret: string = await api.file.upload({ file, toast: { hide: true } });
    const url = extractUrl(ret);
    if (!url) throw new Error(`Unreadable file.upload result for ${upload.name}: ${ret}`);
    const blockUid = await createBlock(runBlockUid, `${upload.caption} ![](${url})`);
    items.push({ caption: upload.caption, url, blockUid });
  }
  return { pageUid, branchBlockUid, runBlockUid, items };
};

const markdownTable = (items: Item[]): string =>
  [
    "| Scenario | Screenshot |",
    "| --- | --- |",
    ...items.map((i) => `| ${i.caption.replace(/\|/g, "\\|")} | ![${i.caption.replace(/[\[\]|]/g, "")}](${i.url}) |`),
  ].join("\n") + "\n";

const main = async (): Promise<void> => {
  const { flags, files } = parseCli(process.argv.slice(2));
  if (files.length === 0) throw new Error("Pass at least one PNG: upload.ts [--slot N] [--branch b] [--label l] a.png[=caption]...");
  const specs = files.map(toUpload);
  const root = git(["rev-parse", "--show-toplevel"]);
  const branch = flags.branch || git(["rev-parse", "--abbrev-ref", "HEAD"]);
  const label =
    flags.label ||
    `${new Date().toISOString().slice(0, 10)} · ${git(["rev-parse", "--short", "HEAD"])} · ${flags.harness || "manual"}`;

  const roam = await loadRoamSession(root);
  const session = await openSession({ roam, slot: flags.slot });
  try {
    const { page } = session;
    await page.waitForFunction("!!window.roamAlphaAPI?.file?.upload && !!window.roamAlphaAPI?.data?.block", undefined, { timeout: 60_000 });
    const written = await page.evaluate(writeEvidence, {
      title: PAGE_TITLE,
      branch,
      label,
      uploads: specs.map(({ name, caption, base64 }) => ({ name, caption, base64 })),
    });
    // Block writes sync to Roam's backend asynchronously; give them time before closing.
    await page.waitForTimeout(Number(flags["settle-ms"] || 5000));
    const result: Result = { page: PAGE_TITLE, ...written };
    const outPath = path.resolve(
      flags.out || path.join(path.dirname(specs[0].file), `pr-evidence-${result.runBlockUid}.md`),
    );
    fs.writeFileSync(outPath, markdownTable(result.items));
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    console.error(`Markdown table: ${outPath}`);
  } finally {
    await session.close();
  }
};

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});

